examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
    MonarchVirtualMessageList(
        messages,
        firstUnreadID: {{firstUnreadId}},
        hasOlder: {{hasOlder}},
        now: now,
        header: { EmptyView() },
        footer: {
            MonarchTypingIndicator([{{typing}}])
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.horizontal)
        },
        row: { message, context in
            MonarchMessageRow(
                MonarchMessageRowAuthor(message.author),
                time: message.time,
                now: now,
                timeStyle: .clock,
                isGrouped: context.isGrouped
            ) {
                Text(message.text)
            }
        }
    )
    .frame(height: 690)
    MonarchButton({{addLabel}}, variant: .secondary, size: .sm) {}
}
.environment(\.calendar, timelineCalendar)

examples.setupTemplate:
