/// Clock times and day separators follow the calendar's time zone, so the example pins it.
private var timelineCalendar: Calendar {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: {{timeZone}}) ?? .gmt
    return calendar
}

examples.setup:
struct Message: MonarchVirtualMessageListItem {
    let id: String
    let time: Date
    let authorID: String?
    let author: String
    let text: String
}
private let now = Date(timeIntervalSince1970: 1_772_452_800)
private let messages = [
    Message(id: "m1", time: Date(timeIntervalSince1970: 1_772_393_400), authorID: "ana", author: "Ana Lopez", text: "Morning! Is the launch checklist up to date?"),
    Message(id: "m2", time: Date(timeIntervalSince1970: 1_772_393_580), authorID: "ana", author: "Ana Lopez", text: "Mostly. Legal sign-off is still open."),
    Message(id: "m3", time: Date(timeIntervalSince1970: 1_772_433_000), authorID: "ben", author: "Ben Okafor", text: "I’ll chase it after standup."),
    Message(id: "m4", time: Date(timeIntervalSince1970: 1_772_436_600), authorID: "chloe", author: "Chloé Martin", text: "Thanks. The press kit is in the shared folder."),
    Message(id: "m5", time: Date(timeIntervalSince1970: 1_772_436_720), authorID: "chloe", author: "Chloé Martin", text: "Looks good. One typo on page two."),
    Message(id: "m6", time: Date(timeIntervalSince1970: 1_772_443_800), authorID: "ana", author: "Ana Lopez", text: "Fixed, and the screenshots are refreshed."),
    Message(id: "m7", time: Date(timeIntervalSince1970: 1_772_449_200), authorID: "ben", author: "Ben Okafor", text: "Great. Shall we freeze copy at 15:00?"),
    Message(id: "m8", time: Date(timeIntervalSince1970: 1_772_449_320), authorID: "ben", author: "Ben Okafor", text: "Works for me."),
]

/// Clock times and day separators follow the calendar's time zone, so the example pins it.
private var timelineCalendar: Calendar {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
    return calendar
}

